set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select pg_temp.check_it((select count(*)from journal_entries where source='payroll')=0,'salary privacy includes global payroll journals');
select pg_temp.check_it((select count(*)from employees)=1,'staff cannot read another employee salary/contact');
select pg_temp.check_it((select count(*)from payrolls)=1,'staff stored payroll is own only');
select pg_temp.check_it((select count(*)from leave_requests)=1,'staff leave read own only');
create function pg_temp.deny(q text,label text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlerrm like 'HRIS:%'or sqlstate='42501' then return;end if;raise;end;raise exception 'FAIL: % accepted',label;end$$;
select pg_temp.deny('insert into leave_requests(employee_id,jenis,tanggal_mulai,status)values(''92000000-0000-0000-0000-000000000002'',''Cuti'',''2026-10-05'',''Disetujui'')','forged leave');
select pg_temp.deny('insert into overtime_requests(employee_id,tanggal,jam,status)values(''92000000-0000-0000-0000-000000000002'',''2026-10-01'',2,''Disetujui'')','forged overtime');
select pg_temp.deny('insert into cash_advances(employee_id,jumlah,status)values(''92000000-0000-0000-0000-000000000002'',100,''Disetujui'')','forged advance');
select pg_temp.deny('insert into reimbursements(employee_id,kategori,jumlah,status,paid_periode)values(''92000000-0000-0000-0000-000000000002'',''Transport'',100,''Dibayar'',''2026-10'')','forged reimbursed marker');
select hris_submit_staff_request('leave','{"jenis":"Cuti","tanggal_mulai":"2026-10-06","tanggal_selesai":"2026-10-06","alasan":"Fiction own request","employee_id":"92000000-0000-0000-0000-000000000002","status":"Disetujui"}',null);
select pg_temp.check_it((select count(*)from leave_requests where tanggal_mulai='2026-10-06'and status='Menunggu')=1,'RPC ignores forged identity and status');
select pg_temp.deny('select hris_submit_staff_request(''leave'',''{"jenis":"Cuti","tanggal_mulai":"2026-10-07","alasan":"Fiction forged employee"}'',''92000000-0000-0000-0000-000000000002'')','staff cannot use HR submit override');
select pg_temp.deny(format('select hris_decide_staff_request(''leave'',%L,true,%L,1,null)',(select id from leave_requests where tanggal_mulai='2026-10-06'),'Fiction self approval'),'self approval');
select hris_submit_staff_request('cash','{"jumlah":100,"tenor_bulan":2,"alasan":"Fiction own advance"}',null);
select pg_temp.deny('select hris_submit_staff_request(''cash'',''{"jumlah":100,"alasan":"Fiction repeated advance"}'',null)','one current own advance');
select pg_temp.deny('select hris_submit_staff_request(''cash'',''{"jumlah":100,"alasan":"Selisih kas kurang saat tutup shift forged"}'',null)','fake automated-shortage prefix');
reset role;
