create function pg_temp.break_cash_audit()returns trigger language plpgsql as $$begin if new.kind in('cash','shift_shortage')then raise exception 'FICTION audit failure';end if;return new;end$$;
create trigger fiction_cash_audit before insert on hris_request_events for each row execute function pg_temp.break_cash_audit();
create function pg_temp.injected(q text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlerrm='FICTION audit failure'then return;end if;raise;end;raise exception 'FAIL: expected audit failure';end$$;
set local role authenticated;
select pg_temp.injected(format('select hris_decide_staff_request(''cash'',%L,true,%L,2,null)',(select id from cash_advances where alasan='Fiction own advance'),'Fiction approved cash'));
select pg_temp.check_it((select count(*)from journal_entries where source='kasbon')=0,'audit failure rolls back complete journal');
select pg_temp.check_it((select disbursed_at from cash_advances where alasan='Fiction own advance')is null,'audit failure rolls back disbursal');
reset role;
drop trigger fiction_cash_audit on hris_request_events;
set local role authenticated;
select hris_decide_staff_request('cash',id,true,'Fiction approved cash',2,null)from cash_advances where alasan='Fiction own advance';
select pg_temp.check_it((select count(*)from journal_entries where source='kasbon')=1,'one approved cash journal');
select pg_temp.check_it((select sum(debit)-sum(credit)from journal_lines where entry_id=(select id from journal_entries where source='kasbon'))=0,'cash journal balanced');
select pg_temp.deny(format('select hris_decide_staff_request(''cash'',%L,true,%L,2,null)',(select id from cash_advances where alasan='Fiction own advance'),'Fiction repeated approval'),'repeat cash approval');
reset role;
insert into cashier_shifts(id,branch_id,opened_by,status,closed_at,closing_balance,expected_cash,selisih)values('98000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001','closed',statement_timestamp(),90,100,-10);
create trigger fiction_cash_audit before insert on hris_request_events for each row execute function pg_temp.break_cash_audit();
set local role authenticated;
select pg_temp.injected('select hris_record_shift_shortage(''98000000-0000-0000-0000-000000000001'')');
select pg_temp.check_it((select count(*)from cash_advances where source_shift_id is not null)=0,'failed audit creates no shortage debt');
select pg_temp.check_it((select count(*)from journal_entries where source='shift')=0,'failed shortage audit rolls back journal');
select pg_temp.check_it(jsonb_array_length(hris_pending_shift_shortages())=1,'closed shortage remains visible for recovery');
reset role;
drop trigger fiction_cash_audit on hris_request_events;
set local role authenticated;
select hris_record_shift_shortage('98000000-0000-0000-0000-000000000001');
select pg_temp.check_it((select count(*)from cash_advances where source_shift_id is not null)=1,'recovery records one verified shortage');
select pg_temp.check_it(jsonb_array_length(hris_pending_shift_shortages())=0,'completed recovery leaves queue');
select pg_temp.deny('select hris_record_shift_shortage(''98000000-0000-0000-0000-000000000001'')','duplicate shortage');
rollback;

